// make-bundle.mjs — build the showcase component bundle (_ds_bundle.js) from
// the committed .jsx sources with Bun's bundler. The bundle is a generated
// artifact: every specimen card loads it as ../../_ds_bundle.js and reads its
// components off the window namespace.
// Usage: bun scripts/make-bundle.mjs [--out <path>]
//   --out   write the bundle to <path> instead of ./_ds_bundle.js. Two runs
//           from the same sources must agree byte-for-byte — that determinism
//           gate (justfile's check-bundle) replaces the retired --check mode.
import { rmSync, mkdirSync, readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';

const args = process.argv.slice(2);
if (args.includes('--help')) { console.log('make-bundle.mjs — build _ds_bundle.js from components/*/*.jsx.\nUsage: bun scripts/make-bundle.mjs [--out <path>] [--help] [--version]'); process.exit(0); }
if (args.includes('--version')) { console.log(JSON.parse(readFileSync('tokens.core.json', 'utf8')).meta.version); process.exit(0); }
const outIdx = args.indexOf('--out');
const outPath = outIdx === -1 ? '_ds_bundle.js' : args[outIdx + 1];
if (!outPath) { console.error('--out requires a path argument'); process.exit(1); }

const NAMESPACE = 'JylhisDesignSystem_61b7cc'; // the suffix is part of the card contract (all card.html read it); keep stable
const root = process.cwd();

// Entry: every component dir's <Name>.jsx, in directory order.
const entries = [];
for (const dir of readdirSync('components').sort()) {
  const p = join('components', dir);
  try { if (!statSync(p).isDirectory()) continue; } catch { continue; }
  for (const f of readdirSync(p).sort()) if (f.endsWith('.jsx')) entries.push(join('components', dir, f));
}
if (!entries.length) { console.error('no component sources found under components/'); process.exit(1); }

// React stays external: specimen cards load the UMD build before this bundle,
// so the bundle reads React off the global. Absolute-path aliases redirect
// `react` and both JSX runtimes to forwarding shims — Bun.build's resolver
// needs absolute paths here (bare-name aliases do not match subpaths).
const outDir = '.ds-bundle-build';
rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
const reactShim = join(outDir, 'react.mjs');
writeFileSync(reactShim, 'export default globalThis.React;\n');
const jsxShim = join(outDir, 'jsx-runtime.mjs');
writeFileSync(jsxShim, `const R = globalThis.React;
const el = (type, props) => R.createElement(type, props, props?.children);
export const jsx = el;
export const jsxs = el;
export const jsxDEV = el;
export const Fragment = R.Fragment;
`);
const entry = join(outDir, 'entry.mjs');
writeFileSync(entry, `// generated by make-bundle.mjs
import React from 'react';
const ns = (globalThis.${NAMESPACE} = globalThis.${NAMESPACE} || {});
${entries.map((e, i) => `import * as c${i} from '${join(root, e)}';`).join('\n')}
${entries.map((_, i) => `Object.assign(ns, c${i});`).join('\n')}
globalThis.React = globalThis.React || React;
`);

// Redirect react + both JSX runtimes to the shims. An onResolve plugin, not
// Bun.build's `alias`: alias matches bare specifiers only on some bun
// versions — 1.3.13 silently passes `react` through to node_modules
// resolution ("Could not resolve: react"), which breaks the hermetic build.
const reactShimAbs = join(root, reactShim), jsxShimAbs = join(root, jsxShim);
const reactPlugin = {
  name: 'react-shims',
  setup(build) {
    build.onResolve({ filter: /^react$/ }, () => ({ path: reactShimAbs }));
    build.onResolve({ filter: /^react\/(jsx-runtime|jsx-dev-runtime)$/ }, () => ({ path: jsxShimAbs }));
  },
};
const result = await Bun.build({
  entrypoints: [entry],
  target: 'browser',
  format: 'iife',
  minify: true,
  define: { 'process.env.NODE_ENV': '"production"' },
  plugins: [reactPlugin],
});
if (!result.success) {
  rmSync(outDir, { recursive: true, force: true });
  console.error(result.logs.map(String).join('\n'));
  process.exit(1);
}
if (result.outputs.length !== 1) { console.error(`expected one build output, got ${result.outputs.length}`); process.exit(1); }
const code = new TextDecoder().decode(await result.outputs[0].arrayBuffer());
rmSync(outDir, { recursive: true, force: true });
const banner = `// _ds_bundle.js — GENERATED from components/*/*.jsx by scripts/make-bundle.mjs. Do not edit by hand.\n`;
const content = banner + code + '\n';

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, content);
console.log(`wrote ${outPath} (${entries.length} sources)`);
